{
  "title": "CSCI-242: Computer Science for Transfer Students - Foundations Lesson Blueprint",
  "learningObjectives": [
    "Define and apply asymptotic notation to describe how algorithm resource use grows with input size.",
    "Explain how loop invariants support correctness proofs through initialization, maintenance, and termination.",
    "Evaluate representation choices for data structures to determine operational efficiency and identify possible errors."
  ],
  "beats": [
    {
      "title": "Course Context and Transfer Goals",
      "claim": "CSCI-242 bridges transfer students' prior programming and data structures background to the skill level of first-year CS students after CSCI 141 and 142.",
      "example": "A transfer student who completed introductory programming courses will use this course to align their problem-solving and algorithmic skills with the university's first-year CS curriculum.",
      "visualDirection": "Display a simple flowchart showing a transfer student's prior coursework feeding into CSCI 242, which then aligns with CSCI 141/142 outcomes.",
      "sourceIds": ["rit-csci-242"]
    },
    {
      "title": "Core Course Focus",
      "claim": "The course centers on developing problem-solving skills and teaching the choice and application of appropriate algorithms and data structures.",
      "example": "Students will practice selecting a hash table for fast key lookups versus a linked list for frequent insertions, based on the problem's access patterns.",
      "visualDirection": "Show a side-by-side comparison of a hash table and a linked list with callout boxes highlighting 'fast lookups' and 'frequent insertions' respectively.",
      "sourceIds": ["rit-csci-242"]
    },
    {
      "title": "Assignment Structure",
      "claim": "Assignments require both a design phase and an implementation phase, with larger programming projects serving as integral learning components.",
      "example": "A homework assignment might ask students to draft a pseudocode design for a priority queue before writing the actual code in a supported language.",
      "visualDirection": "Illustrate a two-step workflow diagram: 'Design Pseudocode' leading to 'Code Implementation', with a larger project icon at the end.",
      "sourceIds": ["rit-csci-242"]
    },
    {
      "title": "Algorithm Analysis Basics",
      "claim": "Algorithm analysis connects a precise problem specification to a correctness argument and resource bounds using asymptotic notation.",
      "example": "Analyzing a sorting algorithm shows that its time complexity grows quadratically with input size, expressed as O(n^2) in asymptotic notation.",
      "visualDirection": "Display a graph with input size on the x-axis and resource use on the y-axis, labeled with 'O(n^2)' to show quadratic growth.",
      "sourceIds": ["mit-algorithms"]
    },
    {
      "title": "Asymptotic Notation",
      "claim": "Asymptotic notation describes how resource use grows with input size, enabling comparisons of algorithm efficiency independent of hardware.",
      "example": "Using Big-O notation, a linear scan is O(n) while a binary search is O(log n), clearly showing the latter scales better for large datasets.",
      "visualDirection": "Show a table comparing 'Linear Search' and 'Binary Search' with their respective O(n) and O(log n) labels and brief growth descriptions.",
      "sourceIds": ["mit-algorithms"]
    },
    {
      "title": "Loop Invariants",
      "claim": "A loop invariant supports a proof by initialization, maintenance, and termination, ensuring loops execute correctly and efficiently.",
      "example": "In a loop that sums an array, the invariant 'sum equals the total of elements processed so far' holds true before each iteration and after the loop ends.",
      "visualDirection": "Display a loop structure with three labeled boxes: 'Initialization', 'Maintenance', and 'Termination', each containing a brief mathematical statement.",
      "sourceIds": ["mit-algorithms"]
    },
    {
      "title": "Data Structure Representations",
      "claim": "Representation choices and invariants determine which operations are efficient and which errors are possible, guiding correct data structure selection.",
      "example": "Choosing an adjacency matrix for a dense graph ensures fast edge lookups, while an adjacency list prevents memory waste on sparse graphs.",
      "visualDirection": "Show two grid layouts: a full matrix with 'fast lookups' and a linked list of nodes with 'sparse graph' and 'memory efficient' labels.",
      "sourceIds": ["opendsa"]
    },
    {
      "title": "Common Data Structures",
      "claim": "Lists represent ordered sequences with position-based operations, while stacks use last-in, first-out access and queues use first-in, first-out access.",
      "example": "A stack processes function calls by returning the most recently added task first, whereas a queue processes customer orders in the exact order they arrive.",
      "visualDirection": "Illustrate a stack with items popping from the top and a queue with items entering at the back and leaving at the front, labeled with their access rules.",
      "sourceIds": ["opendsa"]
    },
    {
      "title": "Trees and Graphs",
      "claim": "Trees represent hierarchical relationships and support recursive traversals, while graphs can be represented with adjacency structures for traversal and path algorithms.",
      "example": "A file system directory tree allows recursive folder browsing, and a road network graph uses adjacency lists to calculate the shortest driving route between two cities.",
      "visualDirection": "Draw a simple tree diagram with parent-child nodes and a graph diagram with nodes and edges, adding arrows to indicate recursive traversal and path finding.",
      "sourceIds": ["opendsa"]
    },
    {
      "title": "Practical Analysis Checklist",
      "claim": "Students must verify that their algorithm design states inputs and outputs, proves correctness, and analyzes time and space before implementation.",
      "example": "Before coding a search routine, students check that the input is a sorted array, the output is the index of the target, and the time complexity is O(log n) using binary search.",
      "visualDirection": "Display a checklist graphic with three boxes: 'State Inputs/Outputs', 'Prove Correctness', and 'Analyze Time/Space', each with a checkbox and brief instruction.",
      "sourceIds": ["mit-algorithms"]
    }
  ]
}
